import json
names={'2e33ccd0-59e7-4eed-b8b7-85178a5f3880':'System Architecture','4d191931-db0b-4aa7-bc66-1ddd12d7028b':'Ingestion Plane','fe19479e-a293-4aee-8440-5ccac79e79c3':'Retrieval Query Path','000eb44a-21ba-4bcc-ba75-31d1d165c256':'Memory & Temporal Graph','48900095-cb57-4483-bcfb-3a3c54e46503':'Video & Audio Pipeline','527296a8-91ba-40fc-a302-613ae03489c2':'Permissions & Control Plane'}
for k,v in names.items():
    d=json.load(open('scene-%s.excalidraw'%k))
    g=d.get('graph') or {}
    n=g.get('nodes',[]); e=g.get('edges',[])
    print('===',v,' nodes=%d edges=%d  versions=%d'%(len(n),len(e),len(d.get('versions',[]))))
    for x in n: print('   ',x.get('id'),'|',x.get('label'),'| icon=',x.get('icon'),'| tier=',x.get('tier'))
    ids={x.get('id') for x in n}
    bad=[(y.get('from'),y.get('to')) for y in e if y.get('from') not in ids or y.get('to') not in ids]
    print('    DANGLING EDGES:',bad if bad else 'none')
    print()
"

